package org.apache.commons.cli;

import java.io.*;
import java.io.PrintWriter;
import java.lang.reflect.Method;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.Comparator;
import java.util.Iterator;
import java.util.List;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class HelpFormatter_renderWrappedText_TriageGen0Test {

    private HelpFormatter formatter;
    private Method renderWrappedTextMethod;

    @Before
    public void setUp() throws Exception {
        formatter = new HelpFormatter();
        // Accessing the protected method via reflection
        renderWrappedTextMethod = HelpFormatter.class.getDeclaredMethod(
                "renderWrappedText", 
                StringBuffer.class, 
                int.class, 
                int.class, 
                String.class
        );
        renderWrappedTextMethod.setAccessible(true);
    }

    private StringBuffer invokeRenderWrappedText(StringBuffer sb, int width, int nextLineTabStop, String text) throws Exception {
        return (StringBuffer) renderWrappedTextMethod.invoke(formatter, sb, width, nextLineTabStop, text);
    }

    @Test
    public void testRenderWrappedText_NoWrapNeeded() throws Exception {
        StringBuffer sb = new StringBuffer();
        String text = "Short text";
        int width = 20;
        int nextLineTabStop = 2;

        StringBuffer result = invokeRenderWrappedText(sb, width, nextLineTabStop, text);

        // Should just append rtrim(text)
        assertEquals("Short text", result.toString());
    }

    @Test
    public void testRenderWrappedText_SingleWrap() throws Exception {
        StringBuffer sb = new StringBuffer();
        // Text that fits in first line but needs wrapping
        String text = "This is a long sentence that will wrap.";
        int width = 15;
        int nextLineTabStop = 4;
        formatter.setNewLine("\n");

        StringBuffer result = invokeRenderWrappedText(sb, width, nextLineTabStop, text);

        // First line: "This is a long" (length 14) + \n
        // Second line: "    sentence that will wrap." (padding 4)
        String expected = "This is a long\n    sentence that will wrap.";
        assertEquals(expected, result.toString());
    }

    @Test
    public void testRenderWrappedText_MultipleWraps() throws Exception {
        StringBuffer sb = new StringBuffer();
        String text = "One two three four five six seven eight nine";
        int width = 10;
        int nextLineTabStop = 2;
        formatter.setNewLine("\n");

        StringBuffer result = invokeRenderWrappedText(sb, width, nextLineTabStop, text);

        // Line 1: "One two" (7) + \n
        // Line 2: "  three" (7) + \n (padding 2 + "three")
        // Line 3: "  four" (6) + \n
        // Line 4: "  five" (6) + \n
        // Line 5: "  six" (5) + \n
        // Line 6: "  seven" (7) + \n
        // Line 7: "  eight" (7) + \n
        // Line 8: "  nine" (6)
        // Note: findWrapPos logic depends on internal implementation of spaces/words
        // Based on code: it trims the text and adds padding.

        String expected = "One two\n  three\n  four\n  five\n  six\n  seven\n  eight\n  nine";
        assertEquals(expected, result.toString());
    }

    @Test
    public void testRenderWrappedText_TextWithTrailingSpaces() throws Exception {
        StringBuffer sb = new StringBuffer();
        String text = "Trailing spaces    ";
        int width = 20;
        int nextLineTabStop = 2;
        formatter.setNewLine("\n");

        StringBuffer result = invokeRenderWrappedText(sb, width, nextLineTabStop, text);

        // rtrim should remove trailing spaces
        assertEquals("Trailing spaces", result.toString());
    }

    @Test
    public void testRenderWrappedText_ImmediateWrapOnPadding() throws Exception {
        StringBuffer sb = new StringBuffer();
        // Text that is very long, causing multiple iterations
        String text = "word word word word word word word";
        int width = 5;
        int nextLineTabStop = 2;
        formatter.setNewLine("\n");

        StringBuffer result = invokeRenderWrappedText(sb, width, nextLineTabStop, text);

        // Width 5 is very small, testing the while(true) loop depth
        // Line 1: "word" (4) + \n
        // Line 2: "  word" (6) -> might wrap again depending on findWrapPos
        // This ensures we hit the pos == -1 inside the loop
        String output = result.toString();
        assertEquals(true, output.contains("\n"));
    }

    @Test
    public void testRenderWrappedText_EmptyString() throws Exception {
        StringBuffer sb = new StringBuffer();
        String text = "";
        int width = 10;
        int nextLineTabStop = 2;

        StringBuffer result = invokeRenderWrappedText(sb, width, nextLineTabStop, text);

        assertEquals("", result.toString());
    }

    @Test
    public void testRenderWrappedText_WidthSmallerThanPadding() throws Exception {
        StringBuffer sb = new StringBuffer();
        String text = "This is a long text";
        int width = 2; // Extremely narrow
        int nextLineTabStop = 5;
        formatter.setNewLine("\n");

        StringBuffer result = invokeRenderWrappedText(sb, width, nextLineTabStop, text);

        // Even with tiny width, it should eventually terminate via pos == -1
        String output = result.toString();
        // Check that it doesn't crash and contains the text
        assertEquals(true, output.contains("This"));
    }
}
